-- StilDoors Solara: точні фото пропущених декорів.
begin;
on conflict (product_slug,option_group,label) do update set image_path=excluded.image_path,is_active=true;
on conflict (product_slug,selections) do update set image_path=excluded.image_path,sort_order=excluded.sort_order,is_active=true;
commit;
select count(*) as точних_фото_варіантів from public.product_variants where product_slug like 'stildoors-solara-%-official' and is_active;
